-                .route_short_addr = slot->device.short_addr,
-                .endpoint = endpoint,
-                .cluster_id = cluster,
-                .retry_count = retries,
-            };
-            ++slot->pending_requests;
-            return &s_async_contexts[i];
-        }
-    }
-    return NULL;
-}
